ns.Locale("deDE", function(L)
	L["crest.alterac.description"] = "Ein zerbrochener Turm auf einem kalten Gipfel. Das Königreich ist fort. Die Bäche sind noch gut."
	L["crest.alterac.name"] = "Der zerbrochene Turm"
	L["crest.arathi.description"] = "Alte stehende Steine im Gras des Hochlands, älter als jeder, der über sie streitet."
	L["crest.arathi.name"] = "Die stehenden Steine"
	L["crest.ashenvale.description"] = "Ein Irrlicht, das zwischen dunklen Bäumen treibt. Der Wald bemerkt jeden Angler, der zu lange bleibt."
	L["crest.ashenvale.name"] = "Das Irrlicht"
	L["crest.azshara.description"] = "Eine Säule eines alten Reiches, an der das Meer emporsteigt. In diesen Ruinen schwimmt noch etwas."
	L["crest.azshara.name"] = "Die gestürzte Säule"
	L["crest.badlands.description"] = "Ein Steinbogen, an dem der Wind zehntausend Jahre gearbeitet hat. Bring dein eigenes Wasser mit."
	L["crest.badlands.name"] = "Der Steinbogen"
	L["crest.barrens.description"] = "Ein Baum mit flacher Krone in den trockenen Ebenen. Jede Oase dort draußen ist irgendwessen Lieblingsplatz."
	L["crest.barrens.name"] = "Die Akazie"
	L["crest.blackrock.description"] = "Ein schwarzer Berg mit Feuer in den Rissen und Ketten vor dem Tor. Angeln in den Lavabecken auf eigene Gefahr."
	L["crest.blackrock.name"] = "Die schwarze Spitze"
	L["crest.blastedlands.description"] = "Ein Tor aus schwarzem Stein mit grünem Feuer darin. Niemand angelt dort wegen der Aussicht."
	L["crest.blastedlands.name"] = "Das brennende Tor"
	L["crest.burningsteppes.description"] = "Ein brennender Berg unter einem Aschehimmel. Das Wasser ist warm genug zum Kochen."
	L["crest.burningsteppes.name"] = "Der brennende Gipfel"
	L["crest.darkshore.description"] = "Eine Mondsichel über grauem Wasser, für Angler, die nach Einbruch der Dunkelheit fischen."
	L["crest.darkshore.name"] = "Die Mondsichel"
	L["crest.darnassus.description"] = "Ein Brunnen, der unter einem großen Baum silbern leuchtet. Der See um ihn birgt die Fische der Stadt."
	L["crest.darnassus.name"] = "Der Silberbrunnen"
	L["crest.deadwind.description"] = "Ein hoher Turm in einem toten Tal. Die Teiche sind still. Zu still, sagen manche, und gehen."
	L["crest.deadwind.name"] = "Der einsame Turm"
	L["crest.desolace.description"] = "Ein großer gehörnter Schädel von einem alten Friedhof. Die Küste ist gnädiger als das Landesinnere."
	L["crest.desolace.name"] = "Der gehörnte Schädel"
	L["crest.dunmorogh.description"] = "Gebogene Hörner über einem Schneefeld. Die Widder dort oben haben ihre eigene Meinung über Fremde."
	L["crest.dunmorogh.name"] = "Der Widder"
	L["crest.durotar.description"] = "Ein Skorpid auf roter Erde. Die Küste ist bessere Gesellschaft als die Skorpide."
	L["crest.durotar.name"] = "Der Skorpid"
	L["crest.duskwood.description"] = "Zwei Augen zwischen schwarzen Bäumen. Angler dort lassen die Laterne brennen und halten die Schnur kurz."
	L["crest.duskwood.name"] = "Augen im Wald"
	L["crest.dustwallow.description"] = "Eine Laterne, die an einer Fischerhütte im Marschnebel brennt."
	L["crest.dustwallow.name"] = "Die Laterne"
	L["crest.easternplague.description"] = "Eine kleine Kapelle, die ihr Licht gegen die Seuche hält. Gleich daneben liegt gutes Wasser."
	L["crest.easternplague.name"] = "Die Kapelle"
	L["crest.elwynn.description"] = "Der erste See, den die meisten Angler je sahen, und die Eiche, unter der sie saßen."
	L["crest.elwynn.name"] = "Die alte Eiche"
	L["crest.felwood.description"] = "Ein verkrümmter Baum mit grünem Feuer in den Adern. Wasch alles, was du dort fängst. Zweimal."
	L["crest.felwood.name"] = "Der verderbte Baum"
	L["crest.feralas.description"] = "Wasser, das zwischen den Riesenbäumen herabstürzt, für Angler, die den langen Weg nehmen."
	L["crest.feralas.name"] = "Die Wasserfälle"
	L["crest.hillsbrad.description"] = "Drei Äpfel aus den Obstgärten am Vorgebirge. Die Forellen unterhalb der Mühle sind fett vom Fallobst."
	L["crest.hillsbrad.name"] = "Drei Äpfel"
	L["crest.hinterlands.description"] = "Große Federn aus den wilden Hügeln, wo mächtige Vögel über den Flüssen nisten."
	L["crest.hinterlands.name"] = "Drei Federn"
	L["crest.hyjal.description"] = "Ein grüner Trieb, der aus alter Glut wächst. Der Berg heilt, und seine Bäche mit ihm."
	L["crest.hyjal.name"] = "Der Schössling"
	L["crest.hyjalcrater.description"] = "Stilles Wasser in einem gebrochenen Ring aus schwarzem Stein. Hier hat einmal etwas gebrannt; der See schweigt darüber."
	L["crest.hyjalcrater.name"] = "Der Kratersee"
	L["crest.ironforge.description"] = "Ein Amboss vor der Schmiede des Berges. Darunter liegt ein See, und Zwerge angeln darin."
	L["crest.ironforge.name"] = "Der Amboss"
	L["crest.lochmodan.description"] = "Ein Damm, der einen Hochlandsee zurückhält. Zwerge haben ihn für die Ewigkeit gebaut, und er hält."
	L["crest.lochmodan.name"] = "Der große Damm"
	L["crest.lordamere.description"] = "Eine bewaldete Insel auf einem weiten grauen See, ein Boot an ihr Ufer gezogen. Stilles Wasser, und reichlich davon."
	L["crest.lordamere.name"] = "Die Seeinsel"
	L["crest.moonglade.description"] = "Ein Geweih über einem stillen See, unter dem Mond. Ein ruhiger Ort, mit Absicht ruhig gehalten."
	L["crest.moonglade.name"] = "Das Geweih"
	L["crest.mulgore.description"] = "Ein geschnitztes Totem auf den weiten Grasebenen, wo die Bäche klar aus den Hügeln fließen."
	L["crest.mulgore.name"] = "Das Totem"
	L["crest.orgrimmar.description"] = "Ein Stacheltor in einer roten Schlucht. Die Becken der Stadt sind tiefer, als sie aussehen."
	L["crest.orgrimmar.name"] = "Das Stacheltor"
	L["crest.redridge.description"] = "Drei rote Gipfel in einem Bergsee, und jeder einzelne spiegelt sich darin."
	L["crest.redridge.name"] = "Drei Gipfel"
	L["crest.riverglades.description"] = "Ein Lastkahn auf einem gewundenen Fluss zwischen grünen Hügeln. Der Handel kommt dort übers Wasser, die Fische auch."
	L["crest.riverglades.name"] = "Der Lastkahn"
	L["crest.searinggorge.description"] = "Ein Tiegel, aus dem flüssiges Gold fließt. Angeln heißt dort Lava, also bring Geduld und eine lange Rute mit."
	L["crest.searinggorge.name"] = "Der Schmelztiegel"
	L["crest.shendralas.description"] = "Ein aufgeschlagenes Buch auf einem zerbrochenen Sockel, gehütet von Leuten, die nie aufgehört haben zu lesen."
	L["crest.shendralas.name"] = "Der offene Foliant"
	L["crest.silithus.description"] = "Ein Skarabäus auf Wüstensand. Die Seen dort sind klein und verdächtig."
	L["crest.silithus.name"] = "Der Skarabäus"
	L["crest.silverpine.description"] = "Silberne Kiefern an einem dunklen Seeufer. Fast jede Nacht heult dort draußen etwas."
	L["crest.silverpine.name"] = "Silberkiefern"
	L["crest.stonetalon.description"] = "Eine große Klaue, die einen Stein umklammert. Bergwasser, kalt und schnell."
	L["crest.stonetalon.name"] = "Die Klaue"
	L["crest.stormwind.description"] = "Weiße Mauern und ein Tor über den Kanälen. Die Stadt befischt ihre eigenen Wasserwege, höflich."
	L["crest.stormwind.name"] = "Die weiße Feste"
	L["crest.stranglethorn.description"] = "Ein Fisch, der hoch aus der Dschungelbrandung springt, als hätte er vom Wettbewerb gehört."
	L["crest.stranglethorn.name"] = "Der Sprung"
	L["crest.swampofsorrows.description"] = "Ein Tempeldach, das aus dem Sumpfwasser ragt. Was darunter liegt, bleibt darunter."
	L["crest.swampofsorrows.name"] = "Der versunkene Schrein"
	L["crest.tanaris.description"] = "Eine Wüstensonne über dem einzigen Schatten weit und breit: dem Ufer."
	L["crest.tanaris.name"] = "Die Wüstensonne"
	L["crest.teldrassil.description"] = "Ein Baum so hoch, dass seine Krone in den Sternen liegt. Seine Wurzeln trinken sehr altes Wasser."
	L["crest.teldrassil.name"] = "Die Sternenkrone"
	L["crest.thousandneedles.description"] = "Steinnadeln, die aus der Ebene ragen. Angle in ihrem Schatten, und behalt den Hut auf."
	L["crest.thousandneedles.name"] = "Die Nadeln"
	L["crest.thunderbluff.description"] = "Ein hoher Tafelberg mit einem Zelt obenauf. Die Becken darunter fangen die Fälle auf, und die Fische mit ihnen."
	L["crest.thunderbluff.name"] = "Der Tafelberg"
	L["crest.tirisfal.description"] = "Eine Fledermaus vor einem kränklichen Mond. Selbst die Fische dort wirken etwas müde."
	L["crest.tirisfal.name"] = "Die Fledermaus"
	L["crest.undercity.description"] = "Eine zerbrochene Krone über grünen Kanälen. Der Hof ist fort. In den Kanälen gibt es noch Fisch."
	L["crest.undercity.name"] = "Die zerbrochene Krone"
	L["crest.ungoro.description"] = "Ein Fußabdruck so groß wie ein Ruderboot. Der Krater hat größere Sorgen als Fische."
	L["crest.ungoro.name"] = "Der Fußabdruck"
	L["crest.veiledsea.description"] = "Ein Schiff, halb verloren in einer Bank aus Seenebel. Hier draußen kommen die Fische aus großer Tiefe herauf, und alles andere auch."
	L["crest.veiledsea.name"] = "Die Nebelbank"
	L["crest.westernplague.description"] = "Eine Krähe auf einem toten Baum über leeren Feldern. Die Bauern gingen. Die Fische nicht."
	L["crest.westernplague.name"] = "Die Krähe"
	L["crest.westfall.description"] = "Flügel, die sich über der Küstenstraße drehen. Das Meer ist näher, als die Bauern zugeben."
	L["crest.westfall.name"] = "Die Windmühle"
	L["crest.wetlands.description"] = "Der Anker eines Hafens, aus dem Schlamm gezogen. Riecht noch ein wenig danach."
	L["crest.wetlands.name"] = "Der Anker"
	L["crest.winterspring.description"] = "Eine Schneeflocke über stillem Wasser, wo Eisangeln echtes Angeln ist."
	L["crest.winterspring.name"] = "Der Frost"
	L["crest.zephras.description"] = "Eine Insel, die auf Wolken schwebt, ihr Schiff am Fels vertäut. Das Wasser liegt weit unten."
	L["crest.zephras.name"] = "Die schwebende Insel"
	L["family.1.name"] = "Schlammschnapper"
	L["family.2.name"] = "Wels"
	L["family.3.name"] = "Gelbschwanz"
	L["family.4.name"] = "Rotkiemer"
	L["family.5.name"] = "Lachs"
	L["family.6.name"] = "Hummer"
	L["family.7.name"] = "Machtfisch"
	L["ledgergood.ledger.binding.abyssal.description"] = "Schwarz wie tiefes Wasser, mit einem bleichen Leuchten, das sich unter der Oberfläche windet. Für Angler, die zehnmal am Grund waren und zurück."
	L["ledgergood.ledger.binding.abyssal.name"] = "Abyssisches Schwarz"
	L["ledgergood.ledger.binding.carapace.description"] = "Der Panzer einer Krabbe, die sich für größer als das Boot hielt, und es fast war. Er kneift die Seiten immer noch zu."
	L["ledgergood.ledger.binding.carapace.name"] = "Krabbenpanzer"
	L["ledgergood.ledger.binding.ember.description"] = "Schuppen von etwas, das zu nah an der Schmiede lebte, im Kern noch warm. Nicht auf dem Nachttisch liegen lassen."
	L["ledgergood.ledger.binding.ember.name"] = "Glutschuppe"
	L["ledgergood.ledger.binding.flywallet.description"] = "Gewachstes Segeltuch mit Fleece vorn, und im Fleece die Fliegen, die funktioniert haben. Die anderen liegen am Grund des Sees."
	L["ledgergood.ledger.binding.flywallet.name"] = "Fliegenmappe"
	L["ledgergood.ledger.binding.heartwood.description"] = "Zwei Bretter aus alter Eiche, vorn ein tief geschnitzter Fisch, und Efeu, den nie jemand gepflanzt hat und der sich nicht ausreden lässt."
	L["ledgergood.ledger.binding.heartwood.name"] = "Geschnitztes Kernholz"
	L["ledgergood.ledger.binding.iridescent.description"] = "Schuppen in jeder Farbe, die das Wasser je hergegeben hat, eine über die nächste gelegt. Sieht nie zweimal gleich aus."
	L["ledgergood.ledger.binding.iridescent.name"] = "Schillernde Schuppe"
	L["ledgergood.ledger.binding.keeper.description"] = "Cremefarbenes Pergament, fast ganz unter Gold begraben. Aufbewahrt für den Angler, dessen Buch nichts mehr zu finden hat."
	L["ledgergood.ledger.binding.keeper.name"] = "Bewahrergold"
	L["ledgergood.ledger.binding.knit.description"] = "Ein Umschlag aus derselben Wolle wie der Pullover des Anglers, samt Knebelknöpfen. Riecht leicht nach Regen und ist wärmer, als er sein dürfte."
	L["ledgergood.ledger.binding.knit.name"] = "Zopfmuster"
	L["ledgergood.ledger.binding.lacquer.description"] = "Dreißig Schichten schwarzer Lack, zwei Koi in Gold und ein mit roter Seide genähter Rücken. Ein Jahr Arbeit, und eine Sekunde bis zum ersten Fingerabdruck."
	L["ledgergood.ledger.binding.lacquer.name"] = "Koi in Schwarzlack"
	L["ledgergood.ledger.binding.legend.description"] = "Blaues Leder mit geprägten Schuppen, und auf dem Deckel drei vergoldete Fische, die einander im selben Kreis jagen."
	L["ledgergood.ledger.binding.legend.name"] = "Drei goldene Fische"
	L["ledgergood.ledger.binding.level10.description"] = "Helleres, weicheres Leder, an den Ecken glatt gegriffen von ein paar Saisons nasser Daumen."
	L["ledgergood.ledger.binding.level10.name"] = "Gegerbtes Leder"
	L["ledgergood.ledger.binding.level20.description"] = "Tiefblaues Leder mit silbernen Linien, in der Farbe eines Hafens in der Abenddämmerung."
	L["ledgergood.ledger.binding.level20.name"] = "Gezeitenblau"
	L["ledgergood.ledger.binding.level30.description"] = "Dunkelgrünes Leder, vergoldet in der Farbe trockenen Schilfs, mit einem leichten Duft von Flussufer."
	L["ledgergood.ledger.binding.level30.name"] = "Schilfgrün"
	L["ledgergood.ledger.binding.level40.description"] = "Tiefrotes Leder und schwere Vergoldung. Fischblut fällt darauf kaum auf."
	L["ledgergood.ledger.binding.level40.name"] = "Ochsenblut"
	L["ledgergood.ledger.binding.level50.description"] = "Schiefergraues Leder mit silberner Prägung, für die Tage, an denen sonst niemand hinausfährt."
	L["ledgergood.ledger.binding.level50.name"] = "Sturmgrau"
	L["ledgergood.ledger.binding.level60.description"] = "Fast schwarzes Leder und helles Gold. Feiner wird das Buch eines Anglers kaum."
	L["ledgergood.ledger.binding.level60.name"] = "Nats Eigenes"
	L["ledgergood.ledger.binding.logbook.description"] = "Leinendeckel und Kalbslederecken, ein Kompass im Deckel und ein Riemen gegen die Gischt. Der Wasserfleck kam gratis dazu."
	L["ledgergood.ledger.binding.logbook.name"] = "Logbuch des Kapitäns"
	L["ledgergood.ledger.binding.monster.description"] = "Schuppige Haut von etwas, das nicht an Land gezogen werden wollte, verschlossen mit einem seiner eigenen Zähne."
	L["ledgergood.ledger.binding.monster.name"] = "Monsterhaut"
	L["ledgergood.ledger.binding.stormglass.description"] = "Eisendeckel, Bandscharniere und ein Fenster mit einem Sturm darin. Niemand weiß mehr, wer den Fisch hineingesetzt hat."
	L["ledgergood.ledger.binding.stormglass.name"] = "Sturmglas-Reliquiar"
	L["ledgergood.ledger.binding.wave.description"] = "Blaues Maroquin mit einer großen eingeprägten Welle, ihr Kamm in Gold abgesetzt. Irgendwo auf ihrer Schulter ist ein sehr kleines Boot."
	L["ledgergood.ledger.binding.wave.name"] = "Brechende Welle"
	L["ledgergood.ledger.soundset.choir.description"] = "Tiefe Stimmen, die aus tiefem Wasser aufsteigen, und darunter singt etwas sehr Großes mit."
	L["ledgergood.ledger.soundset.choir.name"] = "Chor der Tiefe"
	L["ledgergood.ledger.soundset.concertina.description"] = "Eine Phrase auf der Quetschkommode aus einem Seemannslied, das jeder halb kennt, gespielt von jemandem, der es ganz kennt."
	L["ledgergood.ledger.soundset.concertina.name"] = "Konzertina des alten Seebären"
	L["ledgergood.ledger.toaststyle.blueprint.description"] = "In der Werkstatt entworfen, zwischen drei anderen Erfindungen und einem kleinen Feuer. Maßstab eins zu eins, Toleranzen optional, Fang garantiert (nicht garantiert)."
	L["ledgergood.ledger.toaststyle.blueprint.name"] = "Bauplan des Tüftlers"
	L["ledgergood.ledger.toaststyle.cartographer.description"] = "Eine Karte, die nie fertig wird. Jedes Gewässer, das du auswendig kennst, ist mit Tinte eingetragen: Küste, Hügel, die Lotungen vor dem Ufer. Der Rest bleibt in Bleistift und wartet."
	L["ledgergood.ledger.toaststyle.cartographer.name"] = "Folio des Kartografen"
	L["ledgergood.ledger.toaststyle.crier.description"] = "Mittags auf dem Platz verlesen, zwischen dem Brotpreis und dem Ritter, der zum Ritter geschlagen wurde. Jedes Wort davon wahr, plus minus einen Zoll."
	L["ledgergood.ledger.toaststyle.crier.name"] = "Ausruf des Stadtschreiers"
	L["ledgergood.ledger.toaststyle.deep.description"] = "Geschrieben im einzigen Licht am Grund des Sees. Dort unten hält etwas den Fang zwischen den Zähnen und hat es nicht eilig, ihn loszulassen."
	L["ledgergood.ledger.toaststyle.deep.name"] = "Der Tiefseeköder"
	L["ledgergood.ledger.toaststyle.drum.description"] = "Am Feuer über einen Rahmen gespannt, mit der Hand des Clans bemalt und laut genug geschlagen, um das nächste Tal zu wecken. Ein Schlag für jeden Fisch, der eine Geschichte wert ist."
	L["ledgergood.ledger.toaststyle.drum.name"] = "Clantrommel"
	L["ledgergood.ledger.toaststyle.gala.description"] = "Die Nacht des großen Wettstreits, wenn der ganze Hafen seine Lichter aufhängt und niemand vor dem Feuerwerk heimgeht. Diese hier ist für die Angler, die alle drei zurückbrachten."
	L["ledgergood.ledger.toaststyle.gala.name"] = "Wettbewerbsgala"
	L["ledgergood.ledger.toaststyle.glade.description"] = "Bei Mondlicht am Rand eines heiligen Teichs geschrieben, wo das Wasser sich an alles erinnert, was je darin schwamm. Die Irrlichter lesen dir über die Schulter."
	L["ledgergood.ledger.toaststyle.glade.name"] = "Sternenlichtung"
	L["ledgergood.ledger.toaststyle.glass.description"] = "Ein Fenster aus einer Kapelle am Wasser, von Hand verbleit. Die Worte stehen in der einen klaren Scheibe; der Rest ist Rubin, Kobalt und die Farbe späten Lichts."
	L["ledgergood.ledger.toaststyle.glass.name"] = "Kapellenglas"
	L["ledgergood.ledger.toaststyle.hall.description"] = "Aus dem lebenden Fels unter dem Berg gehauen und eingelegt von einem Schmied, der zweimal maß und dreimal prahlte. Die Runen halten die Schmiede warm."
	L["ledgergood.ledger.toaststyle.hall.name"] = "Berghalle"
	L["ledgergood.ledger.toaststyle.hex.description"] = "Von einem Hexendoktor zusammengeschnürt, auf einer Insel, wo die Fische zurückbeißen. Die Maske hat deine Zukunft gesehen: mehr Fische. Die Maske hat Schlimmeres gesehen."
	L["ledgergood.ledger.toaststyle.hex.name"] = "Dschungelfluch"
	L["ledgergood.ledger.toaststyle.ice.description"] = "Fünfzehn Zentimeter gutes schwarzes Eis, ein Loch und viel Warten. Wenn die Fahne hochgeht, rennst du, und die Kälte ist dir egal."
	L["ledgergood.ledger.toaststyle.ice.name"] = "Durchs Eis"
	L["ledgergood.ledger.toaststyle.koi.description"] = "Eine Schriftrolle von einem Maler, der nur Fische malte, und das gut. Der Kreis um den Fang entstand in einem Atemzug."
	L["ledgergood.ledger.toaststyle.koi.name"] = "Tusche und Koi"
	L["ledgergood.ledger.toaststyle.legend.description"] = "Für die Fänge, über die man an den Docks jahrelang streitet. Goldrand, blaue Seide, ein ordentliches Siegel."
	L["ledgergood.ledger.toaststyle.legend.name"] = "Das Seemannsgarn"
	L["ledgergood.ledger.toaststyle.lion.description"] = "Aus dem weißen Stein einer Hafenstadt gehauen, die nie aufhört zu bauen, und unter dem Löwen ihrer Könige gesiegelt. Die Banner wehen nur für einen Fang, der die Fanfaren wert ist."
	L["ledgergood.ledger.toaststyle.lion.name"] = "Charta des Löwen"
	L["ledgergood.ledger.toaststyle.prestige.description"] = "Ochsenblutfarbenes Pergament und goldener Lorbeer, für einen Angler, der von vorn begann und alles noch einmal schaffte."
	L["ledgergood.ledger.toaststyle.prestige.name"] = "Ochsenblut-Pergament"
	L["ledgergood.ledger.toaststyle.shroud.description"] = "Aus dem Tuch gerissen, in dem man dich begraben hat, und wieder zugenäht, als du zum Angeln herausgeklettert bist. Den Fang stört das nicht. Der Fang weiß es nicht."
	L["ledgergood.ledger.toaststyle.shroud.name"] = "Grabtuch"
	L["ledgergood.ledger.toaststyle.slate.description"] = "Heute Morgen angeschrieben, mittags auf Eis. Der Preis ist, was der Fischhändler dir zumuten zu können glaubt."
	L["ledgergood.ledger.toaststyle.slate.name"] = "Schiefertafel des Fischhändlers"
	L["ledgergood.ledger.toaststyle.stitch.description"] = "Gestickt von jemand Geduldigem in den langen Nächten zwischen den Saisons. Jeder Fisch darin kostete einen Abend; die Nadel steckt noch."
	L["ledgergood.ledger.toaststyle.stitch.name"] = "Kreuzstich-Mustertuch"
	L["ledgergood.ledger.toaststyle.totem.description"] = "Am Feuer unter einem sehr weiten Himmel auf eine Haut gemalt, von jemandem, der glaubt, jeder Fisch sei ein Geschenk der Erde. Sag danke."
	L["ledgergood.ledger.toaststyle.totem.name"] = "Totem der Ebenen"
	L["ledgergood.ledger.toaststyle.trophy.description"] = "Walnuss, Messing und vier gute Schrauben. So etwas hängt man über den Kamin und zeigt den Rest des Abends darauf."
	L["ledgergood.ledger.toaststyle.trophy.name"] = "Präparierte Trophäe"
	L["ledgergood.ledger.toaststyle.warband.description"] = "Unter rotem Himmel geschmiedet, in einer Stadt aus Eisen und Groll. Die Feuerbecken brennen für den Clan; die Klauenspuren gelten jedem, der am Fang zweifelte."
	L["ledgergood.ledger.toaststyle.warband.name"] = "Eiserne Kriegshorde"
	L["legend.19803.blurb"] = "Die meisten Angler sehen nur seine Bugwelle. Dieser hier hat lange genug gebremst, um an Land gezogen zu werden."
	L["legend.19803.title"] = "Schrecken der Renner"
	L["legend.19805.blurb"] = "Viel zu schön für einen Wettbewerbstisch, und er scheint es zu wissen."
	L["legend.19805.title"] = "Keefers Konkurrenz"
	L["legend.19806.blurb"] = "Gibt sich königlich und kämpft, als hätte er eine Krone zu verlieren."
	L["legend.19806.title"] = "Schrecken der Königinnen"
	L["line.uncaughtjunk.text"] = "Der Sockel ist abgestaubt und bereit. Das Ausstellungsstück verspätet sich."
	L["line.uncaughtlegend.text"] = "Manche Fische fängt man nur alle Jubeljahre. Diese Seite wartet auf einen."
	L["line.uncaughttreasure.text"] = "Etwas Versiegeltes, noch nicht gefunden."
	L["line.unchartedwaters.text"] = "Unverzeichnete Gewässer. Noch hat sie niemand kartiert."
	L["prestigeframe.castoff.description"] = "Die Reling eines geklinkerten Ruderboots, drei Farbschichten tief, die Riemen quer darüber eingezogen."
	L["prestigeframe.castoff.name"] = "Leinen los"
	L["prestigeframe.constellation.description"] = "Nach dem zehnten setzen sie dich an den Himmel: ein Angler aus Sternen mit Rute und Schnur, und am Ende ein Fisch. Ein Stern mehr in der Krone für jedes Meisterprestige."
	L["prestigeframe.constellation.name"] = "Das Sternbild des Anglers"
	L["prestigeframe.coral.description"] = "Ein Ring aus Perlmutt in einem Riff: rote Koralle auf der einen Seite, ein Seefächer auf der anderen, und immer schwimmt jemand vorbei."
	L["prestigeframe.coral.name"] = "Die Korallengärten"
	L["prestigeframe.dive.description"] = "Ein kupferner Taucherhelm, festgeschraubt und voll Luft gepumpt. Der Angler ist über Bord gegangen, um den Fischen in die Augen zu sehen."
	L["prestigeframe.dive.name"] = "Der Tauchgang"
	L["prestigeframe.jetty.description"] = "Planken vom alten Steg, zu einem Ring gebunden, die noch nach Teer und Ebbe riechen."
	L["prestigeframe.jetty.name"] = "Der Steg"
	L["prestigeframe.leviathan.description"] = "Die Schlange am Grund jeder Seemannsgeschichte, um einen Ring aus altem Gold gewunden, den eigenen Schwanz im Maul."
	L["prestigeframe.leviathan.name"] = "Der Leviathan"
	L["prestigeframe.lighthouse.description"] = "Der Lampenraum am Ende der Landzunge, rundum Glas, und das Licht geht hinaus übers Wasser."
	L["prestigeframe.lighthouse.name"] = "Der Leuchtturm"
	L["prestigeframe.midnight.description"] = "Schwarzes Glas von dort, wo kein Licht hinabreicht, erhellt von den Wesen, die dort leben. Eines davon interessiert sich für dich."
	L["prestigeframe.midnight.name"] = "Die Mitternachtszone"
	L["prestigeframe.none.description"] = "Ein Ring aus Tinte, und eine Vermutung in Bleistift, was einmal darum kommt."
	L["prestigeframe.none.name"] = "Ungeschrieben"
	L["prestigeframe.opensea.description"] = "Eine Kompassrose von der Karte eines Navigators, jeder Strich genau, der Norden in Gold gekrönt."
	L["prestigeframe.opensea.name"] = "Die offene See"
	L["prestigeframe.starward.description"] = "Wo das Meer endet, beginnt der Himmel: eine Armillarsphäre aus Gold und Silber unter der Nacht, und die alten Fische zwischen den Sternen."
	L["prestigeframe.starward.name"] = "Die Sternensee"
	L["prestigeframe.storm.description"] = "Das Steuerrad einer Ketsch im vollen Sturm: Mahagoni, Messing und acht gute Speichen, und darüber reißt der Himmel auf."
	L["prestigeframe.storm.name"] = "Der Sturm"
	L["species.12238.blurb"] = "Breit, träge und grau wie die Küste, nach der er benannt ist. Gibt einen besseren Eintopf ab als einen ersten Eindruck."
	L["species.12238.riddle"] = "Graues Wasser unter alten Bäumen an einem mondhellen Ufer, oder weit im Süden in der Wüste."
	L["species.13422.blurb"] = "Rüstungsschmiede zahlen gut für die Schuppen. Der Aal ist mit dieser Regelung nicht einverstanden."
	L["species.13422.riddle"] = "Ein sich windender Schwarm in tiefem Meerwasser vor den wilderen Küsten."
	L["species.13754.blurb"] = "So schwer, dass manche Angler ihn im Sitzen fangen."
	L["species.13754.riddle"] = "Offene See vor den fernen Küsten, tief genug für die Schweren."
	L["species.13755.blurb"] = "Kommt mit dem Frost. Mehr Arme, als ein Angler vernünftigerweise entwirren kann."
	L["species.13755.riddle"] = "Warme Ufer, sobald das Jahr kalt wird."
	L["species.13756.blurb"] = "Taucht mit den langen Tagen auf und verschwindet mit dem ersten kalten Wind."
	L["species.13756.riddle"] = "Warme Ufer in der warmen Hälfte des Jahres."
	L["species.13757.blurb"] = "Kribbelt. Nicht ablecken."
	L["species.13757.riddle"] = "Ein Knistern in fernen, wilden Gewässern, vom Morgengrauen bis in den späten Abend."
	L["species.13758.blurb"] = "Kiemen wie Glut. Beißt, als meine er es ernst."
	L["species.13758.riddle"] = "Binnengewässer der wilderen Lande, bei Tag oder bei Nacht."
	L["species.13759.blurb"] = "Frisst im Sternenlicht. Wer ihn will, lernt die Dunkelheit zu mögen."
	L["species.13759.riddle"] = "Wilde Gewässer fern der sanften Ufer, nachdem die Sonne untergegangen ist."
	L["species.13760.blurb"] = "Steigt mit der Sonne auf und bleibt lange wach. Niemand weiß, wo er vor der Dämmerung steckt."
	L["species.13760.riddle"] = "Ferne Flüsse und Seen, warm oder kalt, solange es Tag ist."
	L["species.13888.blurb"] = "Kneift zuerst und stellt nie Fragen."
	L["species.13888.riddle"] = "Tiefe, felsige Gewässer an den fernsten Rändern der Welt."
	L["species.13889.blurb"] = "Bleich wie Raureif. Am besten am Fangtag gegessen, was selten gelingt."
	L["species.13889.riddle"] = "Die fernsten Gewässer überhaupt, von gefrorenen Seen bis zu versengten Hügeln."
	L["species.13890.blurb"] = "Trägt seine Panzerung außen und sein Temperament innen. Nimm ein schwereres Messer mit."
	L["species.13890.riddle"] = "Etwas Schweres in den fernsten Gewässern, nachdem die Sonne untergegangen ist."
	L["species.13893.blurb"] = "Der große Vetter. Du brauchst beide Hände und vermutlich einen Freund."
	L["species.13893.riddle"] = "Tiefes Wasser vor einer fernen, vergessenen Küste."
	L["species.1467.blurb"] = "Ein fröhlicher kleiner Fisch, der nicht ahnt, wie viele Köche schon auf ihn warten."
	L["species.1467.riddle"] = "Ein ruhiger Hügelsee im friedlichen Bauernland."
	L["species.16967.blurb"] = "Groß, schnell und gut zu essen. Die meisten werden jemand anderem zuliebe gefangen, was wie Verschwendung wirkt."
	L["species.16967.riddle"] = "Ein breiter Fluss durch nassen, überwucherten Wald im fernen Westen."
	L["species.16968.blurb"] = "Schnappt nach dem Köder, als hätte er den ganzen Tag auf einen Streit gewartet."
	L["species.16968.riddle"] = "Ein trostloses, graues Ufer an einer trockenen, leeren Westküste."
	L["species.16969.blurb"] = "Das Segel ist nur zur Schau, und er weiß es. Kämpft, als hätte er Publikum."
	L["species.16969.riddle"] = "Warme Dschungeluntiefen, wo das Meer bis an die Bäume reicht."
	L["species.16970.blurb"] = "Bunt wie ein Dschungelvogel und an der Schnur doppelt so viel Ärger."
	L["species.16970.riddle"] = "Warme, trübe Untiefen, wo ein Sumpf auf das Meer trifft."
	L["species.19807.blurb"] = "Turnierfisch. Schmeckt nach Sieg, oder zumindest nach einem langen Nachmittag voller Versuche."
	L["species.19807.riddle"] = "Nur solange der große Wettstreit im Dschungel läuft."
	L["species.19975.blurb"] = "Riecht genau so, wie der Name verspricht. Irgendwer, irgendwo will trotzdem ein Dutzend."
	L["species.19975.riddle"] = "Aufgewühltes braunes Wasser, tief im dampfenden Dschungel."
	L["species.21071.blurb"] = "Riecht nach den Hügeln, an denen er vorbeischwimmt."
	L["species.21071.riddle"] = "Kleine Schwärme in Hügeln und Wäldern, mit einem Hauch von Kräutern."
	L["species.21153.blurb"] = "Der Salbei ist erwachsen geworden."
	L["species.21153.riddle"] = "Stattlichere Schwärme mit Kräuterduft, in verschneiten Hügeln und dampfendem Dschungel."
	L["species.251524.blurb"] = "Neu in diesen Gewässern, und niemand weiß so recht, wie er hierherkam."
	L["species.251524.riddle"] = "Leuchtende neue Schwärme auf einem stillen See in den östlichen Hügeln."
	L["species.4603.blurb"] = "Schnell, glänzend und sehr zufrieden mit sich selbst."
	L["species.4603.riddle"] = "Salzige Küsten im Norden und Süden, auf beiden Seiten des Meeres."
	L["species.6289.blurb"] = "Beißt in alles, einmal sogar in einen Gnomenstiefel."
	L["species.6289.riddle"] = "Träge Flüsse in den Landen, wo Helden ihren Anfang nehmen."
	L["species.6291.blurb"] = "Klein, hell und überall. Jedes Anglertagebuch beginnt hier, und niemand gibt zu, wie viele zurück ins Wasser flogen."
	L["species.6291.riddle"] = "Das Allererste, was an der Schnur eines Anfängers zupft, in den sanftesten Gewässern überhaupt."
	L["species.6299.blurb"] = "Sieht übel aus, riecht noch übler und ergibt gekocht etwas, das ein Raptor fressen würde."
	L["species.6299.riddle"] = "Müdes, graues Wasser im düsteren Norden, auf beiden Seiten des Meeres."
	L["species.6303.blurb"] = "Glitschig genug, um den Namen zu verdienen. Gebraten besser, als er eigentlich dürfte."
	L["species.6303.riddle"] = "Flache Küsten, durch die neue Abenteurer waten."
	L["species.6308.blurb"] = "Nur Barteln und Groll. Schmollt am Grund, bis er beschließt zu kämpfen."
	L["species.6308.riddle"] = "Trübe Flüsse auf beiden Seiten des Meeres."
	L["species.6317.blurb"] = "Von Zwergen benannt, die alles danach benennen, wie es sich benimmt, wenn man es festhalten will."
	L["species.6317.riddle"] = "Kaltes Wasser im Hochland, mitten im Zwergenland."
	L["species.6358.blurb"] = "Alchemisten wollen das Öl. Köche wollen nichts damit zu tun haben."
	L["species.6358.riddle"] = "Ein Schwarm, der einen schillernden Film auf dem Küstenwasser hinterlässt."
	L["species.6359.blurb"] = "Warm in der Hand, sogar außerhalb des Wassers."
	L["species.6359.riddle"] = "Wirbelnde Schwärme in der Farbe von Glut, vor Küsten im Norden und Süden."
	L["species.6361.blurb"] = "Die Farben verblassen binnen einer Stunde an Land. Schnell hinsehen."
	L["species.6361.riddle"] = "Offene Küste, ein Stück weiter draußen, als du es gewohnt bist."
	L["species.6362.blurb"] = "Stur an der Schnur, süß auf dem Teller."
	L["species.6362.riddle"] = "Meeresküsten vom nebligen Norden bis in den heißen Süden, wo der Grund steil abfällt."
	L["species.6458.blurb"] = "Weniger ein Fisch als eine Warnung vor dem Wasser. Zweimal waschen, dann noch einmal überlegen."
	L["species.6458.riddle"] = "Verdorbenes Wasser, wo Goblins die ausgedörrten Hügel und Ebenen anbohren."
	L["species.6522.blurb"] = "Verzehr auf eigene Gefahr. Keine zwei Angler, die es taten, erzählen dieselbe Geschichte über die Stunde danach."
	L["species.6522.riddle"] = "Seltsame Schwärme draußen in den trockenen Ebenen, wo selbst das Wasser krank wirkt."
	L["species.8365.blurb"] = "Der Kopf glänzt wirklich. Nein, das ist kein Mithril. Hör auf, den Schmied zu fragen."
	L["species.8365.riddle"] = "Seen und Flüsse in rauerem Land, vom tiefen Wald bis zur kahlen Wüste."
	L["sub.13874.plaque"] = "Zu schwer zum Schwimmen und zu schwer, um sie weit zu tragen. Jemand hat beides versucht."
	L["sub.13875.plaque"] = "Mit Eisen beschlagen und obendrein verschlossen. Was auch drin ist, war die Sorge wert."
	L["sub.13881.plaque"] = "Zu gierig, um mit dem Fressen aufzuhören, und zu satt, um davonzuschwimmen."
	L["sub.13918.plaque"] = "Verstärkt, verschlossen und trotzdem versenkt. Manche Fracht hat einfach kein Glück."
	L["sub.20708.plaque"] = "So dicht versiegelt, dass nie Wasser hineinkam. Der Besitzer offenbar auch nicht."
	L["sub.21113.plaque"] = "Wasserdicht, wie versprochen. Dass sie schwimmt, hat niemand versprochen."
	L["sub.21150.plaque"] = "Das Eisen hat gehalten. Das Schiff, von dem sie stammt, nicht."
	L["sub.21162.plaque"] = "Aufgebläht, glitschig und voller fremdem Glück. Danach Hände waschen."
	L["sub.21164.plaque"] = "Stur bis zuletzt. Was er geschluckt hatte, gab er nur dem Messer preis."
	L["sub.21228.plaque"] = "Mit Mithril beschlagen. Wer sie packte, rechnete mit Ärger, und bekam welchen."
	L["sub.21243.plaque"] = "Groß genug, um eine Geldbörse im Ganzen zu schlucken, und das tat er auch."
	L["sub.6297.plaque"] = "Eine Spende des Wassers. Besitzer unbekannt, und das bleibt besser so."
	L["sub.6301.plaque"] = "Gehörte jemandem, der Wagen fuhr. Sieht immer noch aus, als warte er auf einen."
	L["sub.6307.plaque"] = "Die Tinte ist längst verlaufen. Der Korken hat, das muss man ihm lassen, gehalten."
	L["sub.6351.plaque"] = "Einmal fallen gelassen, wie es aussieht, und dann sicherheitshalber noch einmal."
	L["sub.6352.plaque"] = "Für eine trockene Reise verpackt. Daraus wurde nichts."
	L["sub.6353.plaque"] = "Klein genug, um über Bord zu gehen. Jemand hat es bewiesen."
	L["sub.6354.plaque"] = "Klein, verschlossen und mühsamer zu öffnen, als sie je zu tragen war."
	L["sub.6355.plaque"] = "Gebaut, um alles zu überstehen. Das Meer prüft diese Behauptung noch."
	L["sub.6356.plaque"] = "Jemand hat sie verschlossen, jemand hat sie versenkt, und keiner kam je zurück."
	L["sub.6357.plaque"] = "Dicht versiegelt gegen das Wasser. Das Wasser war geduldig."
	L["sub.6455.plaque"] = "Wohin der Wagen fuhr, wird noch untersucht."
	L["sub.6456.plaque"] = "Bitte das Ausstellungsstück nicht berühren."
	L["sub.6457.plaque"] = "Ein Gnom würde das »fast funktionstüchtig« nennen."
	L["sub.6643.plaque"] = "Ein kleiner Fisch mit großem Appetit und keinem Gespür dafür, was als Futter gilt."
	L["sub.6645.plaque"] = "Hat in etwas viel zu Großes gebissen und es trotzdem geschluckt."
	L["sub.6647.plaque"] = "Hat am Grund gefressen, wo alles landet, was irgendwer fallen lässt."
	L["sub.6717.plaque"] = "Ersatzteile eines Tüftlers, mitten in der Arbeit über Bord gefallen. Er besteht darauf, dass das Boot zuerst leckte."
	L["sub.6718.plaque"] = "Teile für eine aufziehbare Lockente, die Sorte, die explodiert. Wird von den echten Enten ferngehalten."
	L["sub.7973.plaque"] = "Verrät nichts über ihren Inhalt. Öffne sie trotzdem; manchmal ist es eine Perle."
	L["sub.8366.plaque"] = "Hat etwas Glänzendes gefressen. Diesmal vielleicht sogar Mithril."
	L["title.complete.junk.text"] = "Stiefelmuseum auf zwei Beinen"
	L["title.complete.ledger.text"] = "Anglerherz von Azeroth"
	L["title.complete.treasure.text"] = "Hort verlorener Fracht"
	L["title.complete.trophy.text"] = "Zünglein an der Waage"
	L["title.complete.varieties.text"] = "Hort aller Farben"
	L["title.level1.text"] = "Elritze"
	L["title.level10.text"] = "Frischling"
	L["title.level20.text"] = "Schnurkundig"
	L["title.level30.text"] = "Anglerseele"
	L["title.level40.text"] = "Mit allen Wassern gewaschen"
	L["title.level50.text"] = "Gezeitenkundig"
	L["title.level60.text"] = "Nat ebenbürtig"
	L["title.prestige1.text"] = "Wiederkehrende Flut"
	L["title.prestige10.text"] = "Hochwassermarke"
	L["title.prestige5.text"] = "Sog"
	L["title.zonemaster.text"] = "Schutzgeist der Gewässer von {zone}"
end)
